227	interface PolicyApprovalRecord {
228	  id: string;
229	  digest: Buffer;
230	  version: bigint;
231	  confirmations: bigint;
232	  nonce: bigint;
233	  deadline: bigint;
234	  newOwners: Address[];
235	  newConfirmations: bigint;
236	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
237	  signers: Address[];
238	  signatures: Map<Address, Buffer>;
239	  submitted: boolean;
240	}
