242	// ---------- 批量交易分阶段审批 ----------
243	
244	/** 批量交易审批的公开快照（创建 / 加签 / 查询 / 列表时返回） */
245	export interface BatchApproval {
246	  /** 审批标识（由创建序号与审批摘要派生，引擎内唯一） */
247	  id: string;
248	  /** 审批签名摘要（hex，safe-wallet/tx-batch-approval/v1 域） */
249	  digest: string;
250	  /** 创建时绑定的策略版本 */
251	  version: bigint;
252	  /** 创建时绑定的确认数（阈值） */
253	  confirmations: bigint;
254	  /** 创建时绑定的 nonce（提交时才消费） */
255	  nonce: bigint;
256	  deadline: bigint;
257	  /** 有序调用列表（按创建时给定顺序；顺序参与签名） */
258	  calls: BatchCall[];
259	  /** 已收集签名者（按加签顺序，去重） */
260	  signers: Address[];
261	  status: ApprovalStatus;
262	}
263	
264	/** 批量交易审批的内部记录：有序调用 + 版本/nonce 绑定 + 签名收集状态 */
265	interface BatchApprovalRecord {
266	  id: string;
267	  digest: Buffer;
268	  version: bigint;
269	  confirmations: bigint;
270	  nonce: bigint;
271	  deadline: bigint;
272	  /** 有序调用（规范化后的收款地址、原金额、原始 data 副本） */
273	  calls: BatchCall[];
274	  /** 按加签顺序的签名者（与 signatures 的键一一对应） */
275	  signers: Address[];
276	  signatures: Map<Address, Buffer>;
277	  submitted: boolean;
278	}
279	
280	function isNonNegativeInteger(n: bigint, maxBits = 256): boolean {
281	  return n >= 0n && n < 2n ** BigInt(maxBits);
282	}
283	
284	/** 安全标量转换：非法输入（undefined / 字符串等）归一为指定的 Invalid* 错误 */
285	function toBigInt(value: unknown, Invalid: new (msg: string) => Error, field: string): bigint {
286	  if (typeof value === 'bigint') return value;
287	  if (typeof value === 'number' && Number.isSafeInteger(value)) return BigInt(value);
288	  if (typeof value === 'string' && /^\d+$/.test(value.trim())) return BigInt(value.trim());
289	  throw new Invalid(`field "${field}" must be a non-negative integer`);
290	}
291	
292	export class MultiSigWallet {
293	  readonly id: string;
294	  private readonly now: () => bigint;
295	
296	  private owners: Address[];
297	  private readonly ownerSet: Set<Address>;
298	  private confirmations: bigint;
299	  private version: bigint;
300	
301	  /** 下一个期望 nonce（严格递增，顺序提交） */
302	  private nextNonce = 0n;
303	  /** 已消费 nonce（入队即消费；失败终态也不释放） */
304	  private readonly usedNonces = new Set<bigint>();
305	
306	  /** 分阶段审批记录（按创建顺序）；创建不消费 nonce，提交时才消费 */
307	  private readonly approvals = new Map<string, ApprovalRecord>();
308	  private approvalSeq = 0;
309	
310	  /** 策略变更分阶段审批记录（按创建顺序）；与普通交易审批各自独立编号、互不影响 */
311	  private readonly policyApprovals = new Map<string, PolicyApprovalRecord>();
312	  private policyApprovalSeq = 0;
313	
314	  /** 批量交易分阶段审批记录（按创建顺序）；与其他审批命名空间各自独立编号、互不影响 */
315	  private readonly batchApprovals = new Map<string, BatchApprovalRecord>();
316	  private batchApprovalSeq = 0;
317	
318	  readonly queue: ExecutionQueue<WalletTaskPayload>;
319	
320	  constructor(opts: WalletOptions) {
321	    const owners = normalizeOwnerList(opts.owners);
322	    const confirmations = BigInt(opts.confirmations);
323	    if (confirmations <= 0n || confirmations > BigInt(owners.length)) {
324	      throw new InvalidPolicyChange(
325	        `initial confirmations must be within 1..owners (${owners.length}), got ${confirmations}`,
326	      );
327	    }
328	    this.id = opts.id;
329	    this.now = opts.now ?? (() => BigInt(Math.floor(Date.now() / 1000)));
330	    this.owners = owners;
331	    this.ownerSet = new Set(owners);
332	    this.confirmations = confirmations;
333	    this.version = 1n;
334	    this.queue = new ExecutionQueue((task) => this.applyTask(task));
335	  }
336	
337	  // ---------- 只读状态 ----------
338	
339	  get policy(): PolicyState {
340	    return { owners: [...this.owners], confirmations: this.confirmations, version: this.version };
341	  }
342	
343	  get policyVersion(): bigint {
344	    return this.version;
345	  }
346	
347	  get currentOwners(): Address[] {
348	    return [...this.owners];
349	  }
350	
351	  get requiredConfirmations(): bigint {
352	    return this.confirmations;
353	  }
354	
355	  get expectedNonce(): bigint {
356	    return this.nextNonce;
357	  }
358	
359	  isOwner(address: string): boolean {
360	    const a = normalizeAddress(address);
361	    return a !== null && this.ownerSet.has(a);
362	  }
363	
364	  isNonceUsed(nonce: bigint | number): boolean {
365	    return this.usedNonces.has(BigInt(nonce));
366	  }
367	
368	  get tasks(): readonly WalletTask[] {
369	    return this.queue.listTasks();
370	  }
371	
372	  // ---------- 普通交易提交（行为与既有流程一致，载荷不含策略版本） ----------
373	
374	  submitTransaction(sub: TransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
375	    // 原始值透传，由 submit 统一做安全转换，避免在入口抛出原生 TypeError
376	    return this.submit(
377	      'transaction',
378	      {
379	        nonce: sub.nonce,
380	        deadline: sub.deadline,
381	        to: sub.to,
382	        value: sub.value,
383	        data: sub.data ?? new Uint8Array(),
384	      },
385	      signatures,
386	    );
387	  }
388	
389	  // ---------- 原子批量普通交易提交 ----------
390	
391	  /**
392	   * 提交一个有序调用列表作为单个原子批量任务。
393	   *
394	   * 摘要使用 safe-wallet/tx-batch/v1 域标签，绑定钱包标识、nonce、截止时间与按顺序编码的
395	   * 全部调用：单笔交易 / 策略变更 / 取消签名都不能授权批量交易；任一调用的收款方、金额、
396	   * data 或调用顺序、项数变化都会改变摘要。
397	   *
398	   * 校验顺序与单笔提交一致（任一失败都不建任务、不消费 nonce、不改策略/队列）：
399	   *   1) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
400	   *   2) deadline 早于当前时间 → RequestExpired
401	   *   3) 列表（1..64 项）、收款地址、金额、data、nonce 顺序、阈值签名 → InvalidTransactionBatch
402	   *
403	   * 成功时只入队一个批量任务、只消费本次 nonce 并推进 expectedNonce。
404	   */
405	  submitBatchTransaction(sub: BatchTransactionSubmission, signatures: readonly Uint8Array[]): WalletTask {
406	    return this.submit(
407	      'transaction-batch',
408	      {
409	        nonce: sub.nonce,
410	        deadline: sub.deadline,
411	        calls: sub.calls,
412	      },
413	      signatures,
414	    );
415	  }
416	
417	  // ---------- 策略变更提交 ----------
418	
419	  proposePolicyChange(sub: PolicyChangeSubmission, signatures: readonly Uint8Array[]): WalletTask {
420	    return this.submit(
421	      'policy-change',
422	      {
423	        version: sub.version,
424	        nonce: sub.nonce,
425	        deadline: sub.deadline,
426	        newOwners: sub.newOwners,
427	        newConfirmations: sub.newConfirmations,
428	      },
429	      signatures,
430	    );
431	  }
432	
433	  // ---------- 任务取消 ----------
434	
435	  /**
436	   * 取消一个尚未执行的 queued 任务。
437	   *
438	   * 取消摘要使用 safe-wallet/cancel/v1 域标签，绑定钱包标识、目标任务 digest、nonce 与
439	   * 截止时间：签名无法改绑其他任务、其他钱包或其他时间窗口。
440	   *
441	   * 校验顺序（任一失败都不改变任务、不消费 nonce、不改变策略）：
442	   *   1) 字段非法 → InvalidCancellation
443	   *   2) nonce 复用 → NonceAlreadyUsedError（旧请求重放恒得此异常，即使已过期）
444	   *   3) deadline 早于当前时间 → RequestExpired
445	   *   4) nonce 顺序（须等于 expectedNonce）→ InvalidCancellation
446	   *   5) 目标不存在 → TaskNotFoundError；目标已终态 → TaskCancellationConflict
447	   *   6) 阈值签名（当前所有者、去重后达到当前确认数）→ InvalidCancellation
448	   *
449	   * 成功时目标任务由 queued 进入 cancelled 终态并返回：保留原 payload/digest/nonce，
450	   * 记录取消时间与取消摘要；不执行目标效果，不改变 owners/确认数/策略版本，
451	   * 只消费本次 nonce 并推进 expectedNonce。取消不要求任务在队首，也不调整队列顺序。
452	   */
453	  cancelTask(
454	    taskId: string,
455	    nonce: bigint | number,
456	    deadline: bigint | number,
457	    signatures: readonly Uint8Array[],
458	  ): WalletTask;
459	  cancelTask(sub: CancellationSubmission, signatures: readonly Uint8Array[]): WalletTask;
460	  cancelTask(
461	    a: string | CancellationSubmission,
462	    b: readonly Uint8Array[] | bigint | number,
463	    c?: bigint | number,
464	    d?: readonly Uint8Array[],
465	  ): WalletTask {
466	    const sub: CancellationSubmission =
467	      typeof a === 'string' || a === undefined || a === null
468	        ? { taskId: a as string, nonce: b as bigint | number, deadline: c as bigint | number }
469	        : a;
470	    const signatures: readonly Uint8Array[] =
471	      (typeof a === 'string' || a === undefined || a === null ? d : (b as readonly Uint8Array[])) ??
472	      ([] as readonly Uint8Array[]);
473	
474	    // (1) 字段安全转换（畸形输入只抛 InvalidCancellation）
475	    const nonce = toBigInt(sub.nonce, InvalidCancellation, 'nonce');
476	    if (!isNonNegativeInteger(nonce)) {
477	      throw new InvalidCancellation('nonce must be a non-negative integer');
478	    }
479	    // (2) nonce 复用优先于过期判定
480	    if (this.usedNonces.has(nonce)) throw new NonceAlreadyUsedError(nonce);
481	
482	    const deadline = toBigInt(sub.deadline, InvalidCancellation, 'deadline');
483	    if (!isNonNegativeInteger(deadline)) throw new InvalidCancellation('deadline out of range');
484	    // (3) 截止时间
