970	    if (signer === null) {
971	      throw new InvalidApprovalSignatureError('malformed or non-canonical signature');
972	    }
973	    if (!this.ownerSet.has(signer)) {
974	      throw new InvalidApprovalSignatureError('signature does not match approval or signer is not an owner');
975	    }
976	    if (record.signatures.has(signer)) {
977	      throw new DuplicateApprovalSignatureError(`owner already signed: ${signer}`);
978	    }
