994	  /**
995	   * 阈值满足后提交批量交易审批：按既有 safe-wallet/tx-batch/v1 摘要入队一个
996	   * transaction-batch 任务，只消费创建时绑定的 nonce 并推进 expectedNonce；队列与既有
997	   * 终态行为不变（原子回执、FIFO、取消、幂等）。
998	   *
999	   * 校验顺序（任一失败都不消费 nonce、不建任务、不改策略）：
1000	   *   1) 审批不存在 → ApprovalNotFoundError；已提交 → ApprovalAlreadySubmittedError
1001	   *   2) 已过期 → ApprovalExpiredError；版本漂移 → ApprovalPolicyConflictError（过期优先）
1002	   *   3) 签名不足创建时确认数 → ApprovalThresholdNotMetError
1003	   *   4) nonce 已消费 → NonceAlreadyUsedError；nonce ≠ expectedNonce（未消费但顺序错）
1004	   *      → ApprovalNonceConflictError
1005	   */
1006	  submitBatchApproval(approvalId: string): WalletTask {
1007	    const record = this.getBatchApprovalRecord(approvalId);
1008	    this.assertBatchApprovalActive(record);
1009	
1010	    if (BigInt(record.signers.length) < record.confirmations) {
1011	      throw new ApprovalThresholdNotMetError(
1012	        `threshold not met: need ${record.confirmations} distinct owners, got ${record.signers.length}`,
1013	      );
1014	    }
1015	    if (this.usedNonces.has(record.nonce)) throw new NonceAlreadyUsedError(record.nonce);
1016	    if (record.nonce !== this.nextNonce) {
1017	      throw new ApprovalNonceConflictError(`expected nonce ${this.nextNonce}, got ${record.nonce}`);
1018	    }
1019	
1020	    // 按既有批量交易摘要入队（与 submitBatchTransaction 同一域、同一载荷形状）
1021	    const req: TransactionBatchRequest = {
1022	      walletId: this.id,
1023	      nonce: record.nonce,
1024	      deadline: record.deadline,
1025	      calls: record.calls,
1026	    };
1027	    const digest = hashTransactionBatch(req);
1028	    const payload: WalletTaskPayload = {
1029	      kind: 'transaction-batch',
1030	      deadline: record.deadline,
1031	      calls: record.calls.map((call) => ({ to: call.to, value: call.value, data: Buffer.from(call.data) })),
1032	    };
1033	    let task: WalletTask;
1034	    try {
1035	      task = this.queue.enqueue({
1036	        nonce: record.nonce,
1037	        digest: digest.toString('hex'),
1038	        payload,
1039	        submittedAt: this.now(),
1040	      });
1041	    } catch (err) {
1042	      if (err instanceof InvalidQueueStateError) throw new InvalidTransactionBatch(err.message);
1043	      throw err;
1044	    }
1045	    // 原子生效：入队 + 消费 nonce + 审批进入 submitted 终态
1046	    this.usedNonces.add(record.nonce);
1047	    this.nextNonce = record.nonce + 1n;
1048	    record.submitted = true;
1049	    return task;
1050	  }
