1176	  /**
1177	   * 规范化批量调用列表：必须是 1..MAX_BATCH_CALLS 项的数组，每项是对象，
1178	   * 收款地址合法且非零、金额为 256 位以内非负整数、data 必须是 Uint8Array。
1179	   * 保持输入顺序；任何畸形都归为 InvalidTransactionBatch。
1180	   */
1181	  private normalizeBatchCalls(rawCalls: unknown): BatchCall[] {
1182	    if (!Array.isArray(rawCalls) || rawCalls.length === 0) {
1183	      throw new InvalidTransactionBatch('calls must be a non-empty array');
1184	    }
1185	    if (rawCalls.length > MAX_BATCH_CALLS) {
1186	      throw new InvalidTransactionBatch(`too many calls: ${rawCalls.length} > ${MAX_BATCH_CALLS}`);
1187	    }
1188	    const calls: BatchCall[] = [];
1189	    for (const rawCall of rawCalls) {
1190	      if (typeof rawCall !== 'object' || rawCall === null) {
1191	        throw new InvalidTransactionBatch('each batch call must be an object');
1192	      }
1193	      const call = rawCall as Record<string, unknown>;
1194	      const to = normalizeAddress(call.to as string);
1195	      if (to === null || isZeroAddress(to)) {
1196	        throw new InvalidTransactionBatch('invalid or zero recipient address in batch call');
1197	      }
1198	      const value = toBigInt(call.value, InvalidTransactionBatch, 'value');
1199	      if (!isNonNegativeInteger(value)) {
1200	        throw new InvalidTransactionBatch('batch call value out of range');
1201	      }
1202	      if (!(call.data instanceof Uint8Array)) {
1203	        throw new InvalidTransactionBatch('batch call data must be a Uint8Array');
1204	      }
1205	      // 复制一份，避免入队后调用方再改动同一缓冲区影响任务内容/摘要
1206	      calls.push({ to, value, data: Buffer.from(call.data) });
1207	    }
1208	    return calls;
1209	  }
