  );

  // 撤销请求自身 deadline 为未来时间 → 可撤销
  const revoked = wallet.revokeApproval(
    { approvalId: approval.id, nonce: 0n, deadline: 20000n },
    revokeSigs(ownerActors, approval.digest, { deadline: 20000n }),
